                JSONObject directory=account("GET","/api/account/workspaces?session_binding="+parent,null);JSONArray rows=directory.getJSONArray("workspaces");Set<String> seen=new HashSet<>();String a=null,b=null;for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String ws=row.getString("workspace_id");assertTrue("No original or foreign directory scope",allowed.contains(ws)&&seen.add(ws));if(row.getString("role").equals("owner")&&a==null)a=ws;}assertTrue("Only the two Root-owned workspaces",seen.equals(allowed)&&directory.isNull("next_cursor")&&a!=null);for(String ws:allowed)if(!ws.equals(a))b=ws;assertTrue(b!=null);
                JSONObject first=activate(open(a,null));reconcile(first);JSONObject create=new JSONObject().put("id",UUID.randomUUID().toString()).put("kind","page.create").put("target_id",page).put("document_epoch",UUID.randomUUID().toString()).put("body",new JSONObject().put("id",page).put("title","Android actual native owned QA page").put("parent_id",JSONObject.NULL).put("teamspace_id","general")).put("depends_on",new JSONArray());
                JSONObject sync=scoped(first,"POST","/api/sync",new JSONObject().put("workspace_id",a).put("session_binding",first.getString("binding")).put("operations",new JSONArray().put(create)),200);assertTrue("Only own unique QA page created",sync.getJSONArray("results").getJSONObject(0).optString("status").equals("applied"));evidence.put("ownPageId",page).put("ownPageWorkspaceId",a).put("ownPageCreated",true);
                JSONObject actualPage=scoped(first,"GET","/api/pages/"+OutboxPolicy.encode(page)+"/collaboration",null,200);assertEquals("Canonical encoded resource GET",page,actualPage.getJSONObject("page").getString("id"));JSONObject detail=scoped(first,"GET","/api/pages/"+OutboxPolicy.encode(page),null,200);assertEquals("Normal bridge encoded detail GET",page,detail.getJSONObject("page").getString("id"));String uriTitle="Android canonical URI title 🏠";JSONObject metadata=scoped(first,"PATCH","/api/pages/"+OutboxPolicy.encode(page),new JSONObject().put("title",uriTitle).put("revision",detail.getJSONObject("page").getLong("revision")),200);assertEquals("Normal bridge encoded metadata PATCH",uriTitle,metadata.getString("title"));actualPage=scoped(first,"GET","/api/pages/"+OutboxPolicy.encode(page)+"/collaboration",null,200);assertEquals(uriTitle,actualPage.getJSONObject("page").getString("title"));evidence.put("canonicalEncodedDetailGETVerified",true).put("canonicalEncodedMetadataPATCHVerified",true);reconcile(first);String pendingID=UUID.randomUUID().toString(),pendingTitle="Android resumed actual title 🏠";pending(first,page,actualPage.getString("epoch"),pendingID,pendingTitle,actualPage.getJSONObject("page").getString("title"));assertTrue("Actual native SQLite pending",pendingCount(context,first,pendingID)==1);
